package com.storystream.reader_app

import android.app.Application
import com.storystream.reader_app.data.SecureTokenStore
import com.storystream.reader_app.repository.AuthStateHolder
import dagger.hilt.android.HiltAndroidApp
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.SupervisorJob
import kotlinx.coroutines.launch

@HiltAndroidApp
class ReaderApplication : Application() {
    private val startupScope = CoroutineScope(SupervisorJob() + Dispatchers.IO)

    override fun onCreate() {
        super.onCreate()
        SecureTokenStore.prepare(this)

        startupScope.launch {
            try {
                SecureTokenStore.init(this@ReaderApplication)
            } catch (e: Exception) {
                e.printStackTrace()
            }

            AuthStateHolder.initializeFromStoredToken()
        }
    }
}

package com.storystream.reader_app.data

import android.content.Context
import android.content.SharedPreferences
import android.util.Base64
import androidx.core.content.edit
import com.google.crypto.tink.Aead
import com.google.crypto.tink.aead.AeadConfig
import com.google.crypto.tink.aead.AeadKeyTemplates
import com.google.crypto.tink.integration.android.AndroidKeysetManager
import com.google.crypto.tink.KeysetHandle
import java.nio.charset.StandardCharsets

object SecureTokenStore {
    private const val PREFS_NAME = "secure_token_prefs"
    private const val KEYSET_NAME = "master_keyset"
    private const val PREF_SECRET_KEY = "secure_token"
    private const val PREF_REFRESH_KEY = "secure_refresh_token"
    private const val MASTER_KEY_URI = "android-keystore://readerapp_master_key"

    private var aead: Aead? = null
    private var prefs: SharedPreferences? = null

    fun init(context: Context) {
        try {
            AeadConfig.register()
            val manager = AndroidKeysetManager.Builder()
                .withSharedPref(context, PREFS_NAME, KEYSET_NAME)
                .withKeyTemplate(AeadKeyTemplates.AES128_GCM)
                .withMasterKeyUri(MASTER_KEY_URI)
                .build()

            val keysetHandle: KeysetHandle = manager.keysetHandle

            aead = keysetHandle.getPrimitive(Aead::class.java)
            prefs = context.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
        } catch (e: Exception) {
            aead = null
            prefs = null
            throw e
        }
    }

    fun saveToken(token: String) {
        saveAccessToken(token)
    }

    fun saveTokens(accessToken: String, refreshToken: String) {
        saveAccessToken(accessToken)
        val localPrefs = prefs ?: return
        val localAead = aead ?: return
        val ciphertext = localAead.encrypt(refreshToken.toByteArray(StandardCharsets.UTF_8), null)
        val encoded = Base64.encodeToString(ciphertext, Base64.DEFAULT)
        localPrefs.edit {
            putString(PREF_REFRESH_KEY, encoded)
        }
    }

    private fun saveAccessToken(token: String) {
        val localPrefs = prefs ?: return
        val localAead = aead ?: return
        val ciphertext = localAead.encrypt(token.toByteArray(StandardCharsets.UTF_8), null)
        val encoded = Base64.encodeToString(ciphertext, Base64.DEFAULT)
        localPrefs.edit {
            putString(PREF_SECRET_KEY, encoded)
        }
    }

    fun getToken(): String? {
        return getAccessToken()
    }

    fun getAccessToken(): String? {
        val localPrefs = prefs ?: return null
        val localAead = aead ?: return null
        val encoded = localPrefs.getString(PREF_SECRET_KEY, null) ?: return null
        return try {
            val cipher = Base64.decode(encoded, Base64.DEFAULT)
            val plain = localAead.decrypt(cipher, null)
            val token = String(plain, StandardCharsets.UTF_8)
            if (com.storystream.reader_app.util.JwtUtils.isExpired(token)) {
                localPrefs.edit {
                    remove(PREF_SECRET_KEY)
                }
                null
            } else {
                token
            }
        } catch (_: Exception) {
            localPrefs.edit {
                remove(PREF_SECRET_KEY)
            }
            null
        }
    }

    fun getRefreshToken(): String? {
        val localPrefs = prefs ?: return null
        val localAead = aead ?: return null
        val encoded = localPrefs.getString(PREF_REFRESH_KEY, null) ?: return null
        return try {
            val cipher = Base64.decode(encoded, Base64.DEFAULT)
            val plain = localAead.decrypt(cipher, null)
            String(plain, StandardCharsets.UTF_8)
        } catch (_: Exception) {
            localPrefs.edit {
                remove(PREF_REFRESH_KEY)
            }
            null
        }
    }

    fun clearToken() {
        clearTokens()
    }

    fun clearTokens() {
        prefs?.edit {
            remove(PREF_SECRET_KEY)
            remove(PREF_REFRESH_KEY)
        }
    }

    fun replaceToken(token: String) {
        saveAccessToken(token)
    }
}

package com.storystream.reader_app.data

import android.content.Context
import android.content.SharedPreferences
import android.util.Base64
import androidx.core.content.edit
import com.google.crypto.tink.Aead
import com.google.crypto.tink.aead.AeadConfig
import com.google.crypto.tink.aead.AeadKeyTemplates
import com.google.crypto.tink.integration.android.AndroidKeysetManager
import com.google.crypto.tink.KeysetHandle
import java.nio.charset.StandardCharsets

object SecureTokenStore {
    private const val PREFS_NAME = "secure_token_prefs"
    private const val KEYSET_NAME = "master_keyset"
    private const val PREF_SECRET_KEY = "secure_token"
    private const val PREF_REFRESH_KEY = "secure_refresh_token"
    private const val MASTER_KEY_URI = "android-keystore://readerapp_master_key"

    @Volatile
    private var appContext: Context? = null

    @Volatile
    private var initialized = false

    private var aead: Aead? = null
    private var prefs: SharedPreferences? = null

    fun prepare(context: Context) {
        appContext = context.applicationContext
    }

    @Synchronized
    fun init(context: Context) {
        if (initialized && aead != null && prefs != null) return

        try {
            val applicationContext = context.applicationContext
            appContext = applicationContext
            AeadConfig.register()
            val manager = AndroidKeysetManager.Builder()
                .withSharedPref(applicationContext, PREFS_NAME, KEYSET_NAME)
                .withKeyTemplate(AeadKeyTemplates.AES128_GCM)
                .withMasterKeyUri(MASTER_KEY_URI)
                .build()

            val keysetHandle: KeysetHandle = manager.keysetHandle

            aead = keysetHandle.getPrimitive(Aead::class.java)
            prefs = applicationContext.getSharedPreferences(PREFS_NAME, Context.MODE_PRIVATE)
            initialized = true
        } catch (e: Exception) {
            aead = null
            prefs = null
            initialized = false
            throw e
        }
    }

    private fun ensureInitialized() {
        if (initialized && aead != null && prefs != null) return
        val context = appContext ?: return
        runCatching { init(context) }
    }

    fun saveToken(token: String) {
        saveAccessToken(token)
    }

    fun saveTokens(accessToken: String, refreshToken: String) {
        ensureInitialized()
        saveAccessToken(accessToken)
        val localPrefs = prefs ?: return
        val localAead = aead ?: return
        val ciphertext = localAead.encrypt(refreshToken.toByteArray(StandardCharsets.UTF_8), null)
        val encoded = Base64.encodeToString(ciphertext, Base64.DEFAULT)
        localPrefs.edit {
            putString(PREF_REFRESH_KEY, encoded)
        }
    }

    private fun saveAccessToken(token: String) {
        ensureInitialized()
        val localPrefs = prefs ?: return
        val localAead = aead ?: return
        val ciphertext = localAead.encrypt(token.toByteArray(StandardCharsets.UTF_8), null)
        val encoded = Base64.encodeToString(ciphertext, Base64.DEFAULT)
        localPrefs.edit {
            putString(PREF_SECRET_KEY, encoded)
        }
    }

    fun getToken(): String? {
        return getAccessToken()
    }

    fun getAccessToken(): String? {
        ensureInitialized()
        val localPrefs = prefs ?: return null
        val localAead = aead ?: return null
        val encoded = localPrefs.getString(PREF_SECRET_KEY, null) ?: return null
        return try {
            val cipher = Base64.decode(encoded, Base64.DEFAULT)
            val plain = localAead.decrypt(cipher, null)
            val token = String(plain, StandardCharsets.UTF_8)
            if (com.storystream.reader_app.util.JwtUtils.isExpired(token)) {
                localPrefs.edit {
                    remove(PREF_SECRET_KEY)
                }
                null
            } else {
                token
            }
        } catch (_: Exception) {
            localPrefs.edit {
                remove(PREF_SECRET_KEY)
            }
            null
        }
    }

    fun getRefreshToken(): String? {
        ensureInitialized()
        val localPrefs = prefs ?: return null
        val localAead = aead ?: return null
        val encoded = localPrefs.getString(PREF_REFRESH_KEY, null) ?: return null
        return try {
            val cipher = Base64.decode(encoded, Base64.DEFAULT)
            val plain = localAead.decrypt(cipher, null)
            String(plain, StandardCharsets.UTF_8)
        } catch (_: Exception) {
            localPrefs.edit {
                remove(PREF_REFRESH_KEY)
            }
            null
        }
    }

    fun clearToken() {
        clearTokens()
    }

    fun clearTokens() {
        ensureInitialized()
        prefs?.edit {
            remove(PREF_SECRET_KEY)
            remove(PREF_REFRESH_KEY)
        }
    }

    fun replaceToken(token: String) {
        saveAccessToken(token)
    }
}

package com.storystream.reader_app.data

import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class TokenProviderImpl @Inject constructor() : TokenProvider {
    private val _tokenFlow = MutableStateFlow<String?>(SecureTokenStore.getAccessToken())
    override val tokenFlow: StateFlow<String?> = _tokenFlow.asStateFlow()

    override fun getToken(): String? {
        return _tokenFlow.value ?: SecureTokenStore.getAccessToken()
    }

    override fun getRefreshToken(): String? {
        return SecureTokenStore.getRefreshToken()
    }

    override fun updateToken(token: String?) {
        if (token == null) {
            SecureTokenStore.clearTokens()
            _tokenFlow.value = null
        } else {
            SecureTokenStore.saveToken(token)
            _tokenFlow.value = token
        }
    }

    override fun updateTokens(accessToken: String, refreshToken: String?) {
        if (refreshToken != null) {
            SecureTokenStore.saveTokens(accessToken, refreshToken)
        } else {
            SecureTokenStore.saveToken(accessToken)
        }
        _tokenFlow.value = accessToken
    }
}

